#include <openssl/hmac.h>
#include <openssl/evp.h>

namespace fileproc {

struct RequestContext {
    std::string file_id;
    std::string payload;
    std::string signature;
    uint64_t timestamp;
    std::string nonce;
};

class CircuitBreaker {
public:
    enum class State { CLOSED, OPEN, HALF_OPEN };

    CircuitBreaker(int threshold = 5, int timeout_ms = 30000)
        : failure_threshold_(threshold), timeout_ms_(timeout_ms),
          failure_count_(0), state_(State::CLOSED) {}

    bool allow_request() {
        std::lock_guard<std::mutex> lock(mtx_);
        if (state_ == State::OPEN) {
            auto now = std::chrono::steady_clock::now();
            auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
                now - last_failure_time_).count();
            if (elapsed > timeout_ms_) {
                state_ = State::HALF_OPEN;
                return true;
            }
            return false;
        }
        return true;
    }

    void record_success() {
        std::lock_guard<std::mutex> lock(mtx_);
        failure_count_ = 0;
        state_ = State::CLOSED;
    }

    void record_failure() {
        std::lock_guard<std::mutex> lock(mtx_);
        failure_count_++;
        last_failure_time_ = std::chrono::steady_clock::now();
        if (failure_count_ >= failure_threshold_) {
            state_ = State::OPEN;
        }
    }

    State get_state() const {
        std::lock_guard<std::mutex> lock(mtx_);
        return state_;
    }
    int get_failure_count() const {
        std::lock_guard<std::mutex> lock(mtx_);
        return failure_count_;
    }

private:
    int failure_threshold_;
    int timeout_ms_;
    int failure_count_;
    State state_;
    std::chrono::steady_clock::time_point last_failure_time_;
    mutable std::mutex mtx_;
};

class NonceCache {
public:
    NonceCache(size_t max_size = 10000) : max_size_(max_size) {}

    bool check_and_store(const std::string& nonce, uint64_t timestamp) {
        std::lock_guard<std::mutex> lock(mtx_);
        evict_expired();
        if (seen_nonces_.count(nonce)) {
            return false; // replay detected
        }
        if (seen_nonces_.size() >= max_size_) {
            return false; // reject when full rather than evict valid entries
        }
        seen_nonces_.insert(nonce);
        nonce_timestamps_.push_back({nonce, timestamp});
        return true;
    }

    bool was_seen(const std::string& nonce) {
        std::lock_guard<std::mutex> lock(mtx_);
        return seen_nonces_.count(nonce) > 0;
    }

private:
    void evict_expired() {
        auto now = std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
        while (!nonce_timestamps_.empty()) {
            auto& front = nonce_timestamps_.front();
            if (now - front.second > 300) { // 5 min window
                seen_nonces_.erase(front.first);
                nonce_timestamps_.erase(nonce_timestamps_.begin());
            } else {
                break;
            }
        }
    }

    size_t max_size_;
    std::unordered_set<std::string> seen_nonces_;
    std::vector<std::pair<std::string, uint64_t>> nonce_timestamps_;
    std::mutex mtx_;
};

class SignatureVerifier {
public:
    SignatureVerifier(const std::string& secret_key) : secret_key_(secret_key) {}

    std::string compute_signature(const RequestContext& ctx) const {
        std::string data = ctx.file_id + "|" + ctx.payload + "|" +
                          std::to_string(ctx.timestamp) + "|" + ctx.nonce;
        unsigned char result[EVP_MAX_MD_SIZE];
        unsigned int len = 0;
        unsigned char* ok = HMAC(EVP_sha256(), secret_key_.data(), secret_key_.size(),
             reinterpret_cast<const unsigned char*>(data.data()),
             data.size(), result, &len);
        if (ok == nullptr || len == 0) {
            return std::string(); // HMAC failure -> empty signature (verification fails safely)
        }
        return std::string(reinterpret_cast<char*>(result), len);
    }

    bool verify(const RequestContext& ctx) const {
        std::string expected = compute_signature(ctx);
        if (expected.empty()) return false;
        if (expected.size() != ctx.signature.size()) return false;
        // Constant-time comparison
        volatile unsigned char diff = 0;
        for (size_t i = 0; i < expected.size(); i++) {
            diff |= expected[i] ^ ctx.signature[i];
        }
        return diff == 0;
    }

private:
    std::string secret_key_;
};

class FileProcessingService {
public:
    FileProcessingService(const std::string& key)
        : verifier_(key), breaker_(5, 30000) {}

    enum class Result { SUCCESS, INVALID_SIG, REPLAY, CIRCUIT_OPEN, EXPIRED };

    Result process_request(RequestContext& ctx) {
        if (!breaker_.allow_request()) {
            return Result::CIRCUIT_OPEN;
        }

        auto now = std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();

        if (static_cast<uint64_t>(now) - ctx.timestamp > 300) {
            breaker_.record_failure();
            return Result::EXPIRED;
        }

        // Nonce check BEFORE signature verification prevents replay
        // even if nonce was evicted from cache, timestamp check above
        // ensures the window is bounded
        if (!nonce_cache_.check_and_store(ctx.nonce, ctx.timestamp)) {
            return Result::REPLAY;
        }

        if (!verifier_.verify(ctx)) {
            breaker_.record_failure();
            return Result::INVALID_SIG;
        }

        breaker_.record_success();
        execute_file_operation(ctx);
        return Result::SUCCESS;
    }

private:
    void execute_file_operation(const RequestContext& ctx) {
        // Process the file operation
        std::cout << "Processing file: " << ctx.file_id << std::endl;
    }

    SignatureVerifier verifier_;
    CircuitBreaker breaker_;
    NonceCache nonce_cache_;
};

} // namespace fileproc
